-- ---------------------------------------------------------------- reservas, pagos y resenas
-- Montos como los calcula el backend: monto base = noches x precio; el cliente
-- paga ademas 5% de comision de la plataforma y 6% estimado de MercadoPago.
-- En cada alojamiento las reservas no se superponen.

-- R1. Cancelada por el cliente con menos de 48 h (65% reembolso, 35% al anfitrión)
SET @ini = DATE_ADD(CURDATE(), INTERVAL -108 DAY);
SET @n = 5;
SET @p = 89500;
INSERT INTO reserva (estado_reserva, fecha_confirmacion, fecha_inicio, fecha_fin, precio_noche_pactado, precio_total, id_alojamiento, id_cliente) VALUES ('cancelada', TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -116 DAY), '10:00:00'), @ini, DATE_ADD(@ini, INTERVAL @n DAY), @p, @n * @p, @a1, @c29);
SET @r = LAST_INSERT_ID();
SET @base = ROUND(@n * @p, 2);
SET @cplat = ROUND(@base * 0.05, 2);
SET @cmp = ROUND(@base * 0.06, 2);
INSERT INTO pago (id_reserva, estado, monto_base, comision_plataforma, comision_mercadopago, monto_total_cliente, fecha_creacion, fecha_limite_pago, fecha_pago, fecha_transferencia, id_pago_externo, id_transferencia_externa, motivo_cancelacion, monto_reembolsado_cliente, monto_retenido_anfitrion) VALUES (@r, 'reembolsado_parcial', @base, @cplat, @cmp, @base + @cplat + @cmp, TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -116 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -114 DAY), '10:00:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -115 DAY), '16:30:00'), TIMESTAMP(DATE_ADD(CURDATE(), INTERVAL -108 DAY), '09:00:00'), 'demo-mdp-pago-1', 'demo-mdp-payout-1', 'cliente_tardia', @base - ROUND(@base * 0.35, 2), ROUND(@base * 0.35, 2));

